// Generated by OrchestKit Claude Plugin
// Created: 2026-11-05

// A missing /lab/* URL must answer with static HTML only (see the route).

import { describe, expect, it, vi } from "vitest";

vi.mock("@/lib/analytics-server", () => ({
	reportServerEvent: vi.fn(),
	reportServerEvents: vi.fn(),
}));

import { GET } from "@/app/lab/[...slug]/route";
import { reportServerEvent } from "@/lib/analytics-server";
import { RECOVERY_LINKS } from "@/lib/not-found-body";

const get = (path: string) => GET(new Request(`https://orchestkit.dev${path}`));

describe("/lab/* not-found route", () => {
	it("answers a real 404 with HTML that loads no script", async () => {
		const res = get("/lab/not-published-yet.html");
		expect(res.status).toBe(404);
		expect(res.headers.get("content-type")).toBe("text/html; charset=utf-8");
		expect(res.headers.get("cache-control")).toContain("max-age=0");
		const body = await res.text();
		expect(body).not.toMatch(/<script/i);
		expect(body).not.toContain("/_next/");
		expect(body).toContain("/lab/not-published-yet.html");
	});

	it("links the Lab gallery and the shared recovery hops", async () => {
		const body = await get("/lab/x.html").text();
		expect(body).toContain('href="/docs/showcase/lab"');
		for (const link of RECOVERY_LINKS) {
			expect(body).toContain(`href="${link.href.replaceAll("&", "&#38;")}"`);
		}
	});

	it("escapes the requested path", async () => {
		const body = await get("/lab/a'b.html").text();
		expect(body).toContain("/lab/a&#39;b.html");
		expect(body).not.toContain("a'b");
	});

	it("reports the dead lab link server side", () => {
		get("/lab/gone.html");
		expect(reportServerEvent).toHaveBeenCalledWith(
			expect.any(Headers),
			"lab:not-found",
			"/lab/gone.html",
			expect.objectContaining({ ua_family: expect.any(String) }),
		);
	});
});
